  function quickTextComposerControls(){return '<button class="photo-add text-add" type="button" data-add-file aria-label="Добавить фото">＋</button><input id="knowledgeModel" type="hidden" value=""><button class="qt-model-trigger" type="button" data-qt-model-open aria-label="Модель"><span class="qt-model-icon" id="qtModelIcon"></span><b id="qtModelName">GPT-5.6</b><i>⌄</i></button><span class="qt-controls-gap"></span><button class="qt-mic" type="button" data-qt-mic aria-label="Голосовой ввод">'+QT_MIC+'</button><button class="photo-generate quick-send" type="button" data-generate disabled aria-label="Отправить">↑</button>'}
