  function renderQuickTextList(){const list=document.getElementById('qtList');if(!list)return;const items=quickTextState.conversations;if(!items.length){list.innerHTML='<p class="qt-empty">'+(quickTextState.user&&quickTextState.user.signedIn?'История пока пуста':'Войдите, чтобы видеть историю')+'</p>';return}const row=c=>{const id=esc(c.id),active=c.id===quickTextState.conversationId;if(qtRenaming===c.id)return '<div class="qt-item renaming"><input class="qt-rename" data-qt-rename-input="'+id+'" maxlength="120" value="'+esc(c.title||'')+'" aria-label="Название чата"></div>';const menu=qtMenuFor===c.id?'<div class="qt-item-menu"><button type="button" data-qt-pin="'+id+'">'+(c.pinned?'Открепить':'Закрепить')+'</button><button type="button" data-qt-rename="'+id+'">Переименовать</button><button type="button" class="danger" data-qt-delete="'+id+'">'+(qtConfirmDelete===c.id?'Точно удалить?':'Удалить')+'</button></div>':'';return '<div class="qt-item'+(active?' active':'')+(c.pinned?' pinned':'')+(qtMenuFor===c.id?' menu-open':'')+'"><button type="button" class="qt-open" data-qt-open="'+id+'">'+(c.pinned?QT_PIN:'')+'<span>'+esc(c.title||'Chat')+'</span></button><button type="button" class="qt-more" data-qt-more="'+id+'" aria-label="Действия">⋯</button>'+menu+'</div>'};const pinned=items.filter(c=>c.pinned),rest=items.filter(c=>!c.pinned);list.innerHTML=pinned.map(row).join('')+(pinned.length&&rest.length?'<div class="qt-sep" role="separator"></div>':'')+rest.map(row).join('');const input=list.querySelector('[data-qt-rename-input]');if(input){input.focus();input.select()}}
