  function renderQuickTextModel(){const models=quickTextState.models,current=models.find(m=>m.id===quickTextState.model)||models[0];if(!current)return;const input=document.getElementById('knowledgeModel');if(input)input.value=current.id;const name=document.getElementById('qtModelName'),icon=document.getElementById('qtModelIcon');if(name)name.textContent=current.label;if(icon)icon.innerHTML=modelIcon(current);const list=document.getElementById('qtModelList');if(list)list.innerHTML=models.map(m=>'<button type="button" class="qt-model-row'+(m.id===current.id?' active':'')+'" data-qt-model="'+esc(m.id)+'"><span class="qt-model-row-icon">'+modelIcon(m)+'</span><span class="qt-model-row-text"><b>'+esc(m.label)+'</b>'+(m.desc?'<small>'+esc(m.desc)+'</small>':'')+'</span><i>✓</i></button>').join('')}
